// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(1);
        address sender = address(0x1000);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        bool balanceZero = address(c).balance == 0;
        bool isMultiple = blockNum % 15 == 0;
        assertTrue(balanceZero == isMultiple);
    }
}
